mapper.select:
SELECT n.id, n.category, n.title, n.content, n.is_pinned AS pinned, n.views, n.created_at AS createdAt, u.name AS writerName FROM notice n JOIN user u ON n.writer_id = u.id
n.category = #{category}
ORDER BY n.is_pinned DESC, n.created_at DESC

mapper.update:
UPDATE notice 
SET category = #{category}, title = #{title}, content = #{content}, is_pinned = #{pinned} 
WHERE id = #{id}
